server {
    listen 80;
    server_name localhost;
    root /usr/share/nginx/html;

    # 静态资源目录浏览 - /dev/static 指向 /data/wangqiyan/ai-poster-video-split/static
    # ^~ 强制优先级高于所有正则location，绝对不会被其他规则抢走
    location ^~ /dev/static/ {
        alias /data/wangqiyan/ai-poster-video-split/static/;
        autoindex on;
        autoindex_exact_size off;
        autoindex_localtime on;

        add_header Access-Control-Allow-Origin *;
        add_header Access-Control-Allow-Methods 'GET, POST, OPTIONS';
        add_header Access-Control-Allow-Headers 'DNT,User-Agent,X-Requested-With,If-Modified-Since,Cache-Control,Content-Type,Range';

        expires 30d;
        add_header Cache-Control "public, immutable";
    }

    # 原有 /static/ 路径保留
    location /static/ {
        autoindex on;
        autoindex_exact_size off;
        autoindex_localtime on;
    }

    # 允许跨域
    add_header Access-Control-Allow-Origin *;
    add_header Access-Control-Allow-Methods 'GET, POST, OPTIONS';
    add_header Access-Control-Allow-Headers 'DNT,User-Agent,X-Requested-With,If-Modified-Since,Cache-Control,Content-Type,Range';

    # 缓存设置
    location ~* \.(jpg|jpeg|png|gif|ico|css|js|mp4|mov|avi|webp|webm)$ {
        expires 30d;
        add_header Cache-Control "public, immutable";
    }
}
